39	public class AddIndexTask extends BaseTableTask {
40	
41		static final Logger ourLog = LoggerFactory.getLogger(AddIndexTask.class);
42	
43		private String myIndexName;
44		private List<String> myColumns;
45		private List<String> myNullableColumns;
46		private Boolean myUnique;
47		private List<String> myIncludeColumns = Collections.emptyList();
48		/** Should the operation avoid taking a lock on the table */
49		private boolean myOnline;
50	
51		private MetadataSource myMetadataSource = new MetadataSource();
52	
53		public AddIndexTask(String theProductVersion, String theSchemaVersion) {
54			super(theProductVersion, theSchemaVersion);
55		}
56	
57		public void setIndexName(String theIndexName) {
58			myIndexName = theIndexName.toUpperCase(Locale.US);
59		}
60	
61		public void setColumns(List<String> theColumns) {
62			myColumns = theColumns;
63		}
64	
65		public void setUnique(boolean theUnique) {
66			myUnique = theUnique;
67		}
68	
69		public List<String> getNullableColumns() {
70			return myNullableColumns;
71		}
72	
73		public void setNullableColumns(List<String> theNullableColumns) {
74			this.myNullableColumns = theNullableColumns;
75		}
76	
77		@Override
78		public void validate() {
79			super.validate();
80			Validate.notBlank(myIndexName, "Index name not specified");
81			Validate.isTrue(
82					myColumns.size() > 0,
83					"Columns not specified for AddIndexTask " + myIndexName + " on table " + getTableName());
84			Validate.notNull(myUnique, "Uniqueness not specified");
85			setDescription("Add " + myIndexName + " index to table " + getTableName());
86		}
87	
88		@Override
89		public void doExecute() throws SQLException {
90			Set<String> indexNames = JdbcUtils.getIndexNames(getConnectionProperties(), getTableName());
91			if (indexNames.contains(myIndexName)) {
92				logInfo(ourLog, "Index {} already exists on table {} - No action performed", myIndexName, getTableName());
93				return;
94			}
95	
96			logInfo(
97					ourLog,
98					"Going to add a {} index named {} on table {} for columns {}",
99					(myUnique ? "UNIQUE" : "NON-UNIQUE"),
100					myIndexName,
101					getTableName(),
102					myColumns);
103	
104			String sql = generateSql();
105			String tableName = getTableName();
106	
107			try {
108				executeSql(tableName, sql);
109			} catch (Exception e) {
110				String message = e.toString();
111				if (message.contains("already exists")
112						||
113						// The Oracle message is ORA-01408: such column list already indexed
114						// TODO KHS consider db-specific handling here that uses the error code instead of the message so
115						// this is language independent
116						//  e.g. if the db is Oracle than checking e.getErrorCode() == 1408 should detect this case
117						message.contains("already indexed")) {
118					ourLog.warn("Index {} already exists: {}", myIndexName, e.getMessage());
119				} else {
120					throw e;
121				}
122			}
123		}
124	
125		@Nonnull
126		String generateSql() {
127			String unique = myUnique ? "unique " : "";
128			String columns = String.join(", ", myColumns);
129			String includeClause = "";
130			String mssqlWhereClause = "";
131			if (!myIncludeColumns.isEmpty()) {
132				switch (getDriverType()) {
133					case POSTGRES_9_4:
134					case MSSQL_2012:
135					case COCKROACHDB_21_1:
136						includeClause = " INCLUDE (" + String.join(", ", myIncludeColumns) + ")";
137						break;
138					case H2_EMBEDDED:
139					case DERBY_EMBEDDED:
140					case MARIADB_10_1:
141					case MYSQL_5_7:
142					case ORACLE_12C:
143						// These platforms don't support the include clause
144						// Per:
145						// https://use-the-index-luke.com/blog/2019-04/include-columns-in-btree-indexes#postgresql-limitations
146						break;
147				}
148			}
149			if (myUnique && getDriverType() == DriverTypeEnum.MSSQL_2012) {
150				mssqlWhereClause = buildMSSqlNotNullWhereClause();
151			}
152			// Should we do this non-transactionally?  Avoids a write-lock, but introduces weird failure modes.
153			String postgresOnlineClause = "";
154			String msSqlOracleOnlineClause = "";
155			if (myOnline) {
156				switch (getDriverType()) {
157					case POSTGRES_9_4:
158					case COCKROACHDB_21_1:
159						postgresOnlineClause = "CONCURRENTLY ";
160						// This runs without a lock, and can't be done transactionally.
161						setTransactional(false);
162						break;
163					case ORACLE_12C:
164						if (myMetadataSource.isOnlineIndexSupported(getConnectionProperties())) {
165							msSqlOracleOnlineClause = " ONLINE DEFERRED INVALIDATION";
166						}
167						break;
168					case MSSQL_2012:
169						if (myMetadataSource.isOnlineIndexSupported(getConnectionProperties())) {
170							msSqlOracleOnlineClause = " WITH (ONLINE = ON)";
171						}
172						break;
173					default:
174				}
175			}
176	
177			String sql = "create " + unique + "index " + postgresOnlineClause + myIndexName + " on " + getTableName() + "("
178					+ columns + ")" + includeClause + mssqlWhereClause + msSqlOracleOnlineClause;
179			return sql;
180		}
181	
182		@Nonnull
183		private String buildMSSqlNotNullWhereClause() {
184			String mssqlWhereClause = "";
185			if (myNullableColumns == null || myNullableColumns.isEmpty()) {
186				return mssqlWhereClause;
187			}
188	
189			mssqlWhereClause = " WHERE (";
190			mssqlWhereClause += myNullableColumns.stream()
191					.map(column -> column + " IS NOT NULL ")
192					.collect(Collectors.joining("AND"));
193			mssqlWhereClause += ")";
194			return mssqlWhereClause;
195		}
196	
197		public void setColumns(String... theColumns) {
198			setColumns(Arrays.asList(theColumns));
199		}
200	
201		public void setNullableColumns(String... theColumns) {
202			setNullableColumns(Arrays.asList(theColumns));
203		}
204	
205		public void setIncludeColumns(String... theIncludeColumns) {
206			setIncludeColumns(Arrays.asList(theIncludeColumns));
207		}
208	
209		private void setIncludeColumns(List<String> theIncludeColumns) {
210			Validate.notNull(theIncludeColumns);
211			myIncludeColumns = theIncludeColumns;
212		}
213	
214		/**
215		 * Add Index without locking the table.
216		 */
217		public void setOnline(boolean theFlag) {
218			myOnline = theFlag;
219		}
